Ext._define('common.official_journal.document.DiaryWindow', {
    extend: 'core.RestfulWindow',

    rest: 'common.official_journal.document.Restful',

    getFormPanel: function(cfg) {
        if(!this._formPanel)
            this._formPanel = Ext._create('Ext.form.FormPanel', {
                border: false,
                frame: true,
                items: [
                {
                    name: "official_diary",
                    fieldLabel: "Diário oficial",
                    xtype: "rest-autocompletefield",
                    allowBlank: true,
                    rest: "common.official_journal.official_diary.Restful"
                },
                {
                    name: 'pk',
                    xtype: 'hidden',
                    value: cfg.pk
                }
            ]
            });

        return this._formPanel;
    },

    save: function(close) {
        var values = this.getFormPanel().getForm();

        Ext.Ajax.request({
            url: core.callAction('JournalDocument', 'save_info_diary'),
            scope: this,
            params: Ext.applyIf(
                values.getValues()
            ),
            success: function(xhr) {
                this.success && this.success.callback.call(this.success.scope ? this.success.scope : window);
                if(close)
                    this.destroy();
            },
            failure: function() {
                Ext.Msg.show({
                    title: 'Erro de implementação',
                    icon: Ext.Msg.ERROR,
                    buttons: Ext.Msg.OK,
                    msg: 'Ocorreu um erro de implementação do software, favor contacte a equipe de desenvolvimento.'
                });
            }
        });
    }
});

